package org.pocketlore.app;
import android.app.*;import android.content.*;import android.database.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.function.BooleanSupplier;import org.json.*;
public final class RuntimeDurabilityInstrumentation extends RuntimeAdmissionInstrumentation {
 JSONObject report=new JSONObject();JSONArray checks=new JSONArray();Activity activity;File out;
 public void onCreate(Bundle b){args=b;start();}
 void check(boolean b,String label){if(!b)throw new AssertionError(label);checks.put(label);}
 void await(BooleanSupplier b)throws Exception{long end=SystemClock.elapsedRealtime()+15000;while(!b.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(40);check(b.getAsBoolean(),"bounded asynchronous completion");}
 void click(View v,String label){if(v instanceof Button&&((Button)v).getText().toString().equals(label)){v.performClick();return;}if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++)click(((android.view.ViewGroup)v).getChildAt(i),label);}
 String hash(byte[] bytes)throws Exception{java.security.MessageDigest md=java.security.MessageDigest.getInstance("SHA-256");StringBuilder s=new StringBuilder();for(byte b:md.digest(bytes))s.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return s.toString();}
 void close(){if(activity!=null){Activity a=activity;runOnMainSync(a::finish);waitForIdleSync();activity=null;}}
 public void onStart(){if("admission".equals(args.getString("phase"))){super.onStart();return;}boolean pass=false;try{
  out=new File(getTargetContext().getFilesDir(),"runtime-durability-"+args.getString("run")+"-"+args.getString("phase"));check(out.mkdir(),"fresh invocation");JSONObject expected;try(InputStream in=getContext().getAssets().open("expected.json")){expected=new JSONObject(new String(in.readAllBytes(),StandardCharsets.UTF_8)).getJSONObject("rows");}
  JSONObject actual=new JSONObject();try(NotebookStore n=new NotebookStore(getTargetContext())){try(Cursor c=n.getReadableDatabase().rawQuery("SELECT id,created,kind,title,question,body,provenance,note,bookmark FROM entries ORDER BY id",null)){while(c.moveToNext()){JSONArray r=new JSONArray();for(int i=0;i<9;i++)r.put(i<2||i==8?c.getLong(i):c.getString(i));actual.put(""+c.getLong(0),hash(r.toString().getBytes(StandardCharsets.UTF_8)));}}
   check(actual.length()==201,"201 actual rows");for(java.util.Iterator<String> it=expected.keys();it.hasNext();){String key=it.next();check(expected.getString(key).equals(actual.getString(key)),"exact retained row "+key);}
   File export=new File(out,"retained-notebook.md");try(Writer w=new OutputStreamWriter(new FileOutputStream(export),StandardCharsets.UTF_8)){n.exportAll(w,()->false);}report.put("export_sha256",hash(Files.readAllBytes(export.toPath()))).put("export_bytes",export.length());}
  activity=startActivitySync(new Intent(getTargetContext(),SavedActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));SavedActivity saved=(SavedActivity)activity;NotebookActivity.IO.submit(()->{}).get();waitForIdleSync();check(saved.records.getChildCount()<=20,"bounded real history opened");report.put("history_state",saved.pageState.getText().toString());
  runOnMainSync(()->{click(saved.getWindow().getDecorView(),"Notebook actions");click(saved.getWindow().getDecorView(),"Export notebook");});await(()->saved.pendingExport!=null&&saved.exportJob==null);await(()->{android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();return root!=null&&String.valueOf(root.getPackageName()).contains("documentsui");});report.put("picker_opened",true);Thread.sleep(500);for(int i=0;i<5&&saved.pendingExport!=null;i++){sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);Thread.sleep(700);}report.put("picker_return_pending",String.valueOf(saved.pendingExport)).put("picker_return_status",saved.operation.getText().toString());await(()->saved.pendingExport==null);check(saved.operation.getText().toString().contains("cancelled"),"real SAF cancellation");close();
  activity=startActivitySync(new Intent(getTargetContext(),SourceReaderActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("record",201L));SourceReaderActivity reader=(SourceReaderActivity)activity;await(()->reader.entry!=null);check(reader.entry.id==201,"actual retained source201 opened");Thread.sleep(200);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();try(FileOutputStream f=new FileOutputStream(new File(out,"source201.png"))){check(image!=null&&image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f),"actual source screenshot");}close();NotebookActivity.IO.submit(()->{}).get();report.put("row_hashes",actual);pass=true;
 }catch(Throwable e){try{report.put("error",android.util.Log.getStackTraceString(e));}catch(Exception ignored){}}finally{close();try{report.put("status",pass?"PASS":"FAIL").put("run",args.getString("run")).put("phase",args.getString("phase")).put("source_hash",args.getString("source_hash")).put("checks",checks);Files.write(new File(out,"report.json").toPath(),report.toString(2).getBytes(StandardCharsets.UTF_8));Bundle b=new Bundle();b.putString("receipt",report.toString());finish(pass?Activity.RESULT_OK:Activity.RESULT_CANCELED,b);}catch(Exception e){finish(Activity.RESULT_CANCELED,new Bundle());}}}
}
